import sys
d = sys.stdin.read().split("\n")
k = int(d[0])
A = d[1:1+k]
m = int(d[1+k])
B = d[2+k:2+k+m]
bm = {}
for t in B:
    f = t.split()
    bm.setdefault(f[0], []).append(f[1:])
for t in A:
    f = t.split()
    if f[0] in bm:
        for r in bm[f[0]]:
            print(" ".join(f + r))

